pub fn ansi(s:&str)->String{let mut out=String::new();let mut code=false;for l in s.lines(){let l:String=l.chars().filter(|c|!c.is_control()||*c=='\t').collect();if l.starts_with("~~~")||l.starts_with("'''")||l.starts_with("\x60\x60\x60"){code=!code;continue}if code{out.push_str("\x1b[38;2;140;200;160m");for t in l.split_inclusive(|c:char|!c.is_alphanumeric()&&c!='_'){let k=t.trim_end_matches(|c:char|!c.is_alphanumeric()&&c!='_');if ["fn","let","const","pub","struct","enum","impl","use","if","else","return","function","import","export","match","mut"].contains(&k){out.push_str("\x1b[38;2;220;140;255m");out.push_str(t);out.push_str("\x1b[38;2;140;200;160m")}else{out.push_str(t)}}}else if l.starts_with('#'){out.push_str("\x1b[1;36m");out.push_str(l.trim_start_matches('#').trim_start())}else{let mut bold=false;for (i,p) in l.split("**").enumerate(){if i>0{bold=!bold;out.push_str(if bold{"\x1b[1m"}else{"\x1b[22m"})}out.push_str(p)}}out.push_str("\x1b[0m\n")}out}
